@CircuitBreaker(name = "payments", fallbackMethod = "queuePayment")
@Retry(name = "payments")
public PaymentResult charge(Order order) {
    return paymentGateway.charge(order.total(), order.cardToken());
}

private PaymentResult queuePayment(Order order, Throwable cause) {
    return PaymentResult.queued(order.id());
}
